/* ==========================================================================
   Estándar de interfaz v3, Gonzalo Román, tokens.css
   Variante A: Tailwind v4 + shadcn/ui actual (colores en oklch).
   La variante B (Tailwind v3, tripletas HSL) está en tokens-v3.css.

   Uso en una app de Lovable:
   1. Pega en src/index.css, después de  @import "tailwindcss";  y de
      @import "shadcn/tailwind.css";  (si ya existe), sustituyendo el bloque
      :root / @theme inline que trae el proyecto.
   2. Paleta Carbón (21 oct 2026), fija: neutros y tema (--primary,
      --primary-foreground, --accent y --ring) no se cambian por app.
      Vale para las apps nuevas y para la demo de Patatas Arrebola; el Hub,
      carloscanal y la landing mantienen sus colores hasta que Gonzalo
      decida otra cosa. Nada de verde en ninguna parte.
   3. Solo tema claro. No hay .dark a propósito.
   4. Barra lateral carbón con texto blanco, trabajo en blanco, panel en
      gris claro, marino como tinta. Fuente: Lexend (fonts.css).
   5. El tema «anterior» (cielo y ámbar) está en plantillas/tema-anterior.css.
      Solo Hub (customer-hub) y Casa (carloscanal), que no se migran: copian
      ese archivo, lo importan después de este y ponen data-tema="anterior"
      en <html>. Las apps nuevas no lo hacen.
   ========================================================================== */

/* Contraste WCAG verificado (gen_tokens.py, todo OK):
 * texto foreground sobre background                          #0F2747 / #FFFFFF  14.98  OK (mín. 4.5)
 * texto foreground sobre card                                #0F2747 / #FFFFFF  14.98  OK (mín. 4.5)
 * texto foreground sobre muted                               #0F2747 / #F1F2F4  13.38  OK (mín. 4.5)
 * texto muted-foreground sobre background                    #3D5470 / #FFFFFF   7.78  OK (mín. 4.5)
 * texto muted-foreground sobre card                          #3D5470 / #FFFFFF   7.78  OK (mín. 4.5)
 * texto muted-foreground sobre muted                         #3D5470 / #F1F2F4   6.94  OK (mín. 4.5)
 * texto sidebar-foreground sobre sidebar                     #FFFFFF / #2B2F36  13.44  OK (mín. 4.5)
 * texto sidebar-accent-foreground sobre sidebar-accent       #FFFFFF / #474E5A   8.38  OK (mín. 4.5)
 * texto destructive sobre card                               #B42318 / #FFFFFF   6.57  OK (mín. 4.5)
 * texto destructive sobre background                         #B42318 / #FFFFFF   6.57  OK (mín. 4.5)
 * texto destructive sobre muted                              #B42318 / #F1F2F4   5.87  OK (mín. 4.5)
 * texto destructive-foreground sobre destructive             #FFFFFF / #B42318   6.57  OK (mín. 4.5)
 * texto warning-foreground sobre warning                     #0F2747 / #D4901A   5.57  OK (mín. 4.5)
 * texto tag-1-foreground sobre tag-1                         #5E2610 / #E6AF92   6.20  OK (mín. 4.5)
 * texto tag-1-foreground sobre tag-1-mid                     #5E2610 / #ECC2AB   7.31  OK (mín. 4.5)
 * texto tag-1-foreground sobre tag-1-soft                    #5E2610 / #F1D3C2   8.43  OK (mín. 4.5)
 * texto tag-2-foreground sobre tag-2                         #0E2F5A / #A4C0E6   7.16  OK (mín. 4.5)
 * texto tag-2-foreground sobre tag-2-mid                     #0E2F5A / #BAD0EE   8.48  OK (mín. 4.5)
 * texto tag-2-foreground sobre tag-2-soft                    #0E2F5A / #CEDDF2   9.69  OK (mín. 4.5)
 * texto tag-neutral-foreground sobre tag-neutral             #2B2F36 / #E4E6EA  10.75  OK (mín. 4.5)
 * icono status sobre background (no textual)                 #3A4250 / #FFFFFF  10.12  OK (mín. 3.0)
 * icono status sobre muted (no textual)                      #3A4250 / #F1F2F4   9.03  OK (mín. 3.0)
 * icono status-late sobre background (no textual)            #9A6410 / #FFFFFF   4.99  OK (mín. 3.0)
 * icono status-late sobre muted (no textual)                 #9A6410 / #F1F2F4   4.46  OK (mín. 3.0)
 * icono status-done sobre background (no textual)            #0F2747 / #FFFFFF  14.98  OK (mín. 3.0)
 * icono status-done sobre muted (no textual)                 #0F2747 / #F1F2F4  13.38  OK (mín. 3.0)
 * borde input sobre card (no textual)                        #686C74 / #FFFFFF   5.27  OK (mín. 3.0)
 * borde input sobre background (no textual)                  #686C74 / #FFFFFF   5.27  OK (mín. 3.0)
 * borde input sobre muted (no textual)                       #686C74 / #F1F2F4   4.70  OK (mín. 3.0)
 * -- tema carbon
 * [carbon] primary-foreground sobre primary                  #0F2747 / #D4901A   5.57  OK (mín. 4.5)
 * [carbon] accent-foreground sobre accent                    #0F2747 / #F4D58F  10.53  OK (mín. 4.5)
 * [carbon] muted-foreground sobre accent (fila seleccionada) #3D5470 / #F4D58F   5.47  OK (mín. 4.5)
 * [carbon] destructive sobre accent (fila seleccionada)      #B42318 / #F4D58F   4.62  OK (mín. 4.5)
 * [carbon] ring sobre background (foco, no textual)          #8A5A0B / #FFFFFF   5.92  OK (mín. 3.0)
 * [carbon] ring sobre card (foco, no textual)                #8A5A0B / #FFFFFF   5.92  OK (mín. 3.0)
 * [carbon] ring sobre muted (foco, no textual)               #8A5A0B / #F1F2F4   5.28  OK (mín. 3.0)
 * [carbon] ring sobre accent (barra de foco, no textual)     #8A5A0B / #F4D58F   4.16  OK (mín. 3.0)
 * [carbon] icono status sobre accent (no textual)            #3A4250 / #F4D58F   7.11  OK (mín. 3.0)
 * [carbon] icono status-late sobre accent (no textual)       #9A6410 / #F4D58F   3.51  OK (mín. 3.0)
 * [carbon] sidebar-ring (primary) sobre sidebar (foco, no textual) #D4901A / #2B2F36   4.99  OK (mín. 3.0)
 * [carbon] sidebar-ring (primary) sobre sidebar-accent (foco, no textual) #D4901A / #474E5A   3.11  OK (mín. 3.0)
 */

:root {
  --radius: 0.375rem; /* 6px: lg 6, md 4, sm 2 */
  /* Neutros fijos */
  --background: oklch(1.000 0 0); /* #FFFFFF blanco: área de trabajo */
  --foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino (tinta) */
  --card: oklch(1.000 0 0); /* #FFFFFF blanco: diálogos y tarjetas */
  --card-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --popover: oklch(1.000 0 0); /* #FFFFFF blanco: menús y paleta */
  --popover-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --secondary: oklch(0.961 0.003 264.5); /* #F1F2F4 gris claro: panel de detalle, chips */
  --secondary-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --muted: oklch(0.961 0.003 264.5); /* #F1F2F4 gris claro: cabecera de tabla, avisos, skeleton */
  --muted-foreground: oklch(0.439 0.054 253.8); /* #3D5470 pizarra (secundario) */
  --accent-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --destructive: oklch(0.500 0.182 29.5); /* #B42318 rojo: solo negativos, retrasos y errores */
  --destructive-foreground: oklch(1.000 0 0); /* #FFFFFF blanco */
  --warning: oklch(0.704 0.143 73.9); /* #D4901A ámbar (solo relleno) */
  --warning-foreground: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --status: oklch(0.377 0.026 261.6); /* #3A4250 carbón: iconos de estado (trazo 1,75) */
  --status-late: oklch(0.549 0.113 70.8); /* #9A6410 ocre: icono de estado con retraso */
  --status-done: oklch(0.273 0.067 256.5); /* #0F2747 marino: hecho */
  --tag-1: oklch(0.797 0.076 49.0); /* #E6AF92 terracota fuerte: etiqueta tono 1 */
  --tag-1-mid: oklch(0.845 0.058 50.3); /* #ECC2AB terracota media */
  --tag-1-soft: oklch(0.887 0.041 51.4); /* #F1D3C2 terracota suave */
  --tag-1-foreground: oklch(0.345 0.088 40.6); /* #5E2610 texto de etiqueta tono 1 */
  --tag-2: oklch(0.800 0.062 256.1); /* #A4C0E6 azul fuerte: etiqueta tono 2 */
  --tag-2-mid: oklch(0.851 0.048 256.2); /* #BAD0EE azul medio */
  --tag-2-soft: oklch(0.893 0.033 256.8); /* #CEDDF2 azul suave */
  --tag-2-foreground: oklch(0.308 0.086 256.6); /* #0E2F5A texto de etiqueta tono 2 */
  --tag-neutral: oklch(0.925 0.006 264.5); /* #E4E6EA gris: etiqueta de envase o contenedor */
  --tag-neutral-foreground: oklch(0.304 0.014 261.7); /* #2B2F36 texto de etiqueta neutra */
  --border: oklch(0.873 0.007 268.5); /* #D3D5DA línea gris: solo bordes necesarios */
  --input: oklch(0.531 0.013 264.5); /* #686C74 borde de control (3:1 en blanco y gris claro) */
  --sidebar: oklch(0.304 0.014 261.7); /* #2B2F36 carbón: barra lateral */
  --sidebar-foreground: oklch(1.000 0 0); /* #FFFFFF blanco */
  --sidebar-accent: oklch(0.422 0.022 261.3); /* #474E5A carbón claro: elemento activo */
  --sidebar-accent-foreground: oklch(1.000 0 0); /* #FFFFFF blanco */
  --sidebar-border: oklch(0.304 0.014 261.7); /* #2B2F36 igual que la barra: sin borde visible */
  --chart-2: oklch(0.273 0.067 256.5); /* #0F2747 marino */
  --chart-3: oklch(0.439 0.054 253.8); /* #3D5470 pizarra */
  --chart-4: oklch(0.800 0.062 256.1); /* #A4C0E6 azul */
  --chart-5: oklch(0.500 0.182 29.5); /* #B42318 rojo */
  /* Tema Carbón: acento ámbar, fila seleccionada y barra de foco */
  --primary: oklch(0.704 0.143 73.9); /* #D4901A */
  --primary-foreground: oklch(0.273 0.067 256.5); /* #0F2747 */
  --accent: oklch(0.883 0.095 86.6); /* #F4D58F */
  --ring: oklch(0.508 0.105 71.9); /* #8A5A0B */
  /* Alias: siguen al tema automáticamente */
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-ring: var(--primary);
  --chart-1: var(--primary);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-status: var(--status);
  --color-status-late: var(--status-late);
  --color-status-done: var(--status-done);
  --color-tag-1: var(--tag-1);
  --color-tag-1-mid: var(--tag-1-mid);
  --color-tag-1-soft: var(--tag-1-soft);
  --color-tag-1-foreground: var(--tag-1-foreground);
  --color-tag-2: var(--tag-2);
  --color-tag-2-mid: var(--tag-2-mid);
  --color-tag-2-soft: var(--tag-2-soft);
  --color-tag-2-foreground: var(--tag-2-foreground);
  --color-tag-neutral: var(--tag-neutral);
  --color-tag-neutral-foreground: var(--tag-neutral-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-accent: var(--accent);
  --color-ring: var(--ring);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-chart-1: var(--chart-1);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: var(--radius); /* topes: nada más redondo que 6px */
  --radius-2xl: var(--radius);
  --font-sans: "Lexend", Verdana, sans-serif;
  --font-cifras: "Cifras GR", "Lexend", Verdana, sans-serif;
  /* Escala densa para Lexend: 12 / 13 / 15 / 22 */
  --text-xs: 0.75rem;   --text-xs--line-height: 1rem;
  --text-sm: 0.8125rem; --text-sm--line-height: 1.25rem;
  --text-base: 0.9375rem; --text-base--line-height: 1.375rem;
  --text-2xl: 1.375rem; --text-2xl--line-height: 1.75rem;
}

@layer base {
  html { font-family: var(--font-sans); color: var(--foreground); background: var(--background); }
  .tabular-nums { font-family: var(--font-cifras); font-variant-numeric: tabular-nums; }
}

/* Lexend (OFL), autoalojada. Estándar v3. */
@font-face{font-family:'Lexend';font-style:normal;font-weight:300 700;font-display:swap;src:url(/fonts/lexend-latin-ext.woff2) format('woff2');unicode-range:U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF}
@font-face{font-family:'Lexend';font-style:normal;font-weight:300 700;font-display:swap;src:url(/fonts/lexend-latin.woff2) format('woff2');unicode-range:U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD}
/* Cifras GR: solo 0-9 de Lexend con ancho fijo (gen_cifras.py). Se usa con tabular-nums. */
@font-face{font-family:'Cifras GR';font-style:normal;font-weight:400;font-display:swap;src:url(/fonts/cifras-gr-400.woff2) format('woff2');unicode-range:U+0030-0039}
@font-face{font-family:'Cifras GR';font-style:normal;font-weight:500;font-display:swap;src:url(/fonts/cifras-gr-500.woff2) format('woff2');unicode-range:U+0030-0039}
@font-face{font-family:'Cifras GR';font-style:normal;font-weight:600;font-display:swap;src:url(/fonts/cifras-gr-600.woff2) format('woff2');unicode-range:U+0030-0039}
